import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"大壯","description":"周易集解 - 大壯","frontmatter":{"title":"大壯","description":"周易集解 - 大壯"},"headers":[],"relativePath":"classics/jijie/034.md","filePath":"classics/jijie/034.md"}'),l={name:"classics/jijie/034.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大壯" tabindex="-1">大壯 <a class="header-anchor" href="#大壯" aria-label="Permalink to “大壯”">​</a></h1><h2 id="大壯-1" tabindex="-1">大壯 <a class="header-anchor" href="#大壯-1" aria-label="Permalink to “大壯”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>大壯，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以終遯，故受之以大壯。</p><p>韓康伯曰：遯，君子以遠小人。遯而後通，何可終耶。陽盛陰消，君子道勝也。</p><p>虞翻曰：陽息，泰也。壯，傷也。大謂四，失位為陰所乘。兌為毀折傷，與五易位乃得正，故利貞也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大壯，大者壯也。剛以動，故壯。大壯利貞，大者正也。正大而天地之情可見矣。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>侯果曰：此卦本坤。陰柔消弱，剛大長壯，故曰大壯也。</p><p>荀爽曰：乾剛震動，陽從下升，陽氣大動，故壯也。</p><p>虞翻曰：謂四進之五乃得正，故大者正也。</p><p>虞翻曰：正大謂四之五成需。以離日見天，坎月見地，故天地之情可見也矣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷在天上，大壯。君子以非禮弗履。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：乾下震上，故曰雷在天上。一曰：雷，陽氣也。陽至於上卦。能助於天威，大壯之象也。</p><p>陸績曰：天尊雷卑，君子見卑乘尊，終必消除，故象以為戒，非禮不履。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，壯於趾，徵兇有孚。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：趾謂四。徵，行也。震足為趾，為徵。初得位，四不徵之五，故兇。坎為孚，謂四上之五成坎，已得應四，故有孚。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：壯於趾，其孚窮也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：應在乾終，故其孚窮也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，貞吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二貞吉，以中也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：變得位，故貞吉。動體離，故以中也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：應在震也。三，陽，君子。小人謂上。上逆，故用壯。謂二已變離，離為罔，三乘二，故君子用罔。體乾，夕惕，故貞厲也。</p><p>荀爽曰：三與五同功，為兌，故曰羊。終始陽位，故曰羝。藩，謂四也。三欲觸四而危之，四反羸其角。角，謂五也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：小人用壯，君子罔也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：藩，謂四也。九四體震，為竹葦，故稱藩也。三互乾兌，乾壯，兌羊，故曰羝羊。四藩未決，三宜勿往，用壯觸藩，求應於上，故角被拘羸矣。</p><p>案：自三至五，體兌為羊，四既是藩，五為羊角，即｢羝羊觸藩，羸其角｣之象也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，貞吉，悔亡。藩決不羸，壯於大輿之腹。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：藩決不贏，尚往也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：失位悔也。之正得中，故貞吉而悔亡矣。體夬象，故藩決。震四上處五，則藩毀壞，故藩決不羸。坤為大車、為腹；四之五折坤，故｢壯於大車之腹｣。而《象》曰｢尚往者｣，謂上之五。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，喪羊於易，無悔。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：四動成泰。坤為喪也。乾為易。四上之五，兌還屬乾。故喪羊於易。動各得正，而處中和，故無悔矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：喪羊於易，位不當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>案：謂四五陰陽失正。陰陽失正，故曰位不當也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在三，故羝羊觸藩。遂，進也。謂四已之五，體坎。上能變之巽，巽為進退。故｢不能退，不能遂｣。退則失位，上則乘剛，故無攸利。坎為艱，得位應三利上，故艱則吉。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不能退，不能遂，不詳也。艱則吉，咎不長也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：乾善為詳，不得三應，故不詳也。</p><p>虞翻曰：巽為長。動失位，為咎。不變之巽。故咎不長也。</p>',69)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
